/// CostDetailsType contains the cost as calculated by Charging Station based on provided TariffType.
///
/// NOTE: Reservation is not shown as a _chargingPeriod_, because it took place outside of the transaction.
///
/// The OCPP 2.1 `CostDetails` data type.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct CostDetails {
    /// The `totalCost` member.
    #[serde(rename = "totalCost")]
    pub total_cost: TotalCost,
    /// The `totalUsage` member.
    #[serde(rename = "totalUsage")]
    pub total_usage: TotalUsage,
    /// The `chargingPeriods` member.
    #[serde(rename = "chargingPeriods")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub charging_periods: Option<Vec<ChargingPeriod>>,
    /// If set to true, then Charging Station has failed to calculate the cost.
    #[serde(rename = "failureToCalculate")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failure_to_calculate: Option<bool>,
    /// Optional human-readable reason text in case of failure to calculate.
    #[serde(rename = "failureReason")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub failure_reason: Option<String>,
    /// The `customData` member.
    #[serde(rename = "customData")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub custom_data: Option<crate::types::CustomData>,
}

impl CostDetails {
    /// Creates a `CostDetails` from its required fields.
    #[must_use]
    pub fn new(total_cost: TotalCost, total_usage: TotalUsage) -> Self {
        Self {
            total_cost,
            total_usage,
            charging_periods: None,
            failure_to_calculate: None,
            failure_reason: None,
            custom_data: None,
        }
    }

    /// Sets the optional `chargingPeriods` field.
    #[must_use]
    pub fn with_charging_periods(mut self, value: Vec<ChargingPeriod>) -> Self {
        self.charging_periods = Some(value);
        self
    }

    /// Sets the optional `failureToCalculate` field.
    #[must_use]
    pub fn with_failure_to_calculate(mut self, value: bool) -> Self {
        self.failure_to_calculate = Some(value);
        self
    }

    /// Sets the optional `failureReason` field.
    #[must_use]
    pub fn with_failure_reason(mut self, value: impl Into<String>) -> Self {
        self.failure_reason = Some(value.into());
        self
    }

    /// Sets the optional `customData` field.
    #[must_use]
    pub fn with_custom_data(mut self, value: crate::types::CustomData) -> Self {
        self.custom_data = Some(value);
        self
    }
}

impl Validate for CostDetails {
    fn validate_at(&self, path: &mut ValidationPath, out: &mut Violations) {
        path.push_key("totalCost");
        Validate::validate_at(&self.total_cost, path, out);
        path.pop();
        path.push_key("totalUsage");
        Validate::validate_at(&self.total_usage, path, out);
        path.pop();
        path.push_key("chargingPeriods");
        if let Some(value) = &self.charging_periods {
            validate::list_len(value.len(), Some(1), None, path, out);
            for (index, item) in value.iter().enumerate() {
                path.push_index(index);
                Validate::validate_at(item, path, out);
                path.pop();
            }
        }
        path.pop();
        path.push_key("failureReason");
        if let Some(value) = &self.failure_reason {
            validate::string(value.as_str(), None, Some(500), path, out);
        }
        path.pop();
        path.push_key("customData");
        if let Some(value) = &self.custom_data {
            Validate::validate_at(value, path, out);
        }
        path.pop();
    }
}

