impl Validate for DERChargingParameters {
    fn validate_at(&self, path: &mut ValidationPath, out: &mut Violations) {
        path.push_key("evSupportedDERControl");
        if let Some(value) = &self.ev_supported_der_control {
            validate::list_len(value.len(), Some(1), None, path, out);
            for (index, item) in value.iter().enumerate() {
                path.push_index(index);
                Validate::validate_at(item, path, out);
                path.pop();
            }
        }
        path.pop();
        path.push_key("evInverterManufacturer");
        if let Some(value) = &self.ev_inverter_manufacturer {
            validate::string(value.as_str(), None, Some(50), path, out);
        }
        path.pop();
        path.push_key("evInverterModel");
        if let Some(value) = &self.ev_inverter_model {
            validate::string(value.as_str(), None, Some(50), path, out);
        }
        path.pop();
        path.push_key("evInverterSerialNumber");
        if let Some(value) = &self.ev_inverter_serial_number {
            validate::string(value.as_str(), None, Some(50), path, out);
        }
        path.pop();
        path.push_key("evInverterSwVersion");
        if let Some(value) = &self.ev_inverter_sw_version {
            validate::string(value.as_str(), None, Some(50), path, out);
        }
        path.pop();
        path.push_key("evInverterHwVersion");
        if let Some(value) = &self.ev_inverter_hw_version {
            validate::string(value.as_str(), None, Some(50), path, out);
        }
        path.pop();
        path.push_key("evIslandingDetectionMethod");
        if let Some(value) = &self.ev_islanding_detection_method {
            validate::list_len(value.len(), Some(1), None, path, out);
            for (index, item) in value.iter().enumerate() {
                path.push_index(index);
                Validate::validate_at(item, path, out);
                path.pop();
            }
        }
        path.pop();
        path.push_key("customData");
        if let Some(value) = &self.custom_data {
            Validate::validate_at(value, path, out);
        }
        path.pop();
    }
}

