/// The OCPP 2.1 `OCSPRequestData` data type.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct OCSPRequestData {
    /// The `hashAlgorithm` member.
    #[serde(rename = "hashAlgorithm")]
    pub hash_algorithm: HashAlgorithm,
    /// The hash of the issuer’s distinguished
    /// name (DN), that must be calculated over the DER
    /// encoding of the issuer’s name field in the certificate
    /// being checked.
    #[serde(rename = "issuerNameHash")]
    pub issuer_name_hash: String,
    /// The hash of the DER encoded public key:
    /// the value (excluding tag and length) of the subject
    /// public key field in the issuer’s certificate.
    #[serde(rename = "issuerKeyHash")]
    pub issuer_key_hash: String,
    /// The string representation of the
    /// hexadecimal value of the serial number without the
    /// prefix "0x" and without leading zeroes.
    #[serde(rename = "serialNumber")]
    pub serial_number: String,
    /// This contains the responder URL (Case insensitive).
    #[serde(rename = "responderURL")]
    pub responder_url: String,
    /// The `customData` member.
    #[serde(rename = "customData")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub custom_data: Option<crate::types::CustomData>,
}

impl OCSPRequestData {
    /// Creates a `OCSPRequestData` from its required fields.
    #[must_use]
    pub fn new(
        hash_algorithm: HashAlgorithm,
        issuer_name_hash: impl Into<String>,
        issuer_key_hash: impl Into<String>,
        serial_number: impl Into<String>,
        responder_url: impl Into<String>,
    ) -> Self {
        Self {
            hash_algorithm,
            issuer_name_hash: issuer_name_hash.into(),
            issuer_key_hash: issuer_key_hash.into(),
            serial_number: serial_number.into(),
            responder_url: responder_url.into(),
            custom_data: None,
        }
    }

    /// Sets the optional `customData` field.
    #[must_use]
    pub fn with_custom_data(mut self, value: crate::types::CustomData) -> Self {
        self.custom_data = Some(value);
        self
    }
}

impl Validate for OCSPRequestData {
    fn validate_at(&self, path: &mut ValidationPath, out: &mut Violations) {
        path.push_key("hashAlgorithm");
        Validate::validate_at(&self.hash_algorithm, path, out);
        path.pop();
        path.push_key("issuerNameHash");
        validate::string(self.issuer_name_hash.as_str(), None, Some(128), path, out);
        path.pop();
        path.push_key("issuerKeyHash");
        validate::string(self.issuer_key_hash.as_str(), None, Some(128), path, out);
        path.pop();
        path.push_key("serialNumber");
        validate::string(self.serial_number.as_str(), None, Some(40), path, out);
        path.pop();
        path.push_key("responderURL");
        validate::string(self.responder_url.as_str(), None, Some(2000), path, out);
        path.pop();
        path.push_key("customData");
        if let Some(value) = &self.custom_data {
            Validate::validate_at(value, path, out);
        }
        path.pop();
    }
}

