/// The PriceLevelScheduleType is modeled after the same type that is defined in ISO 15118-20, such that if it is supplied by an EMSP as a signed EXI message, the conversion from EXI to JSON (in OCPP) and back to EXI (for ISO 15118-20) does not change the digest and therefore does not invalidate the signature.
///
/// The OCPP 2.1 `PriceLevelSchedule` data type.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct PriceLevelSchedule {
    /// The `priceLevelScheduleEntries` member.
    #[serde(rename = "priceLevelScheduleEntries")]
    pub price_level_schedule_entries: Vec<PriceLevelScheduleEntry>,
    /// Starting point of this price schedule.
    #[serde(rename = "timeAnchor")]
    pub time_anchor: crate::types::DateTime,
    /// Unique ID of this price schedule.
    #[serde(rename = "priceScheduleId")]
    pub price_schedule_id: i32,
    /// Defines the overall number of distinct price level elements used across all PriceLevelSchedules.
    #[serde(rename = "numberOfPriceLevels")]
    pub number_of_price_levels: i32,
    /// Description of the price schedule.
    #[serde(rename = "priceScheduleDescription")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub price_schedule_description: Option<String>,
    /// The `customData` member.
    #[serde(rename = "customData")]
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub custom_data: Option<crate::types::CustomData>,
}

impl PriceLevelSchedule {
    /// Creates a `PriceLevelSchedule` from its required fields.
    #[must_use]
    pub fn new(
        price_level_schedule_entries: Vec<PriceLevelScheduleEntry>,
        time_anchor: impl Into<crate::types::DateTime>,
        price_schedule_id: i32,
        number_of_price_levels: i32,
    ) -> Self {
        Self {
            price_level_schedule_entries,
            time_anchor: time_anchor.into(),
            price_schedule_id,
            number_of_price_levels,
            price_schedule_description: None,
            custom_data: None,
        }
    }

    /// Sets the optional `priceScheduleDescription` field.
    #[must_use]
    pub fn with_price_schedule_description(mut self, value: impl Into<String>) -> Self {
        self.price_schedule_description = Some(value.into());
        self
    }

    /// Sets the optional `customData` field.
    #[must_use]
    pub fn with_custom_data(mut self, value: crate::types::CustomData) -> Self {
        self.custom_data = Some(value);
        self
    }
}

impl Validate for PriceLevelSchedule {
    fn validate_at(&self, path: &mut ValidationPath, out: &mut Violations) {
        path.push_key("priceLevelScheduleEntries");
        validate::list_len(
            self.price_level_schedule_entries.len(),
            Some(1),
            Some(100),
            path,
            out,
        );
        for (index, item) in self.price_level_schedule_entries.iter().enumerate() {
            path.push_index(index);
            Validate::validate_at(item, path, out);
            path.pop();
        }
        path.pop();
        path.push_key("priceScheduleId");
        validate::int_range(i64::from(self.price_schedule_id), Some(0), None, path, out);
        path.pop();
        path.push_key("numberOfPriceLevels");
        validate::int_range(
            i64::from(self.number_of_price_levels),
            Some(0),
            None,
            path,
            out,
        );
        path.pop();
        path.push_key("priceScheduleDescription");
        if let Some(value) = &self.price_schedule_description {
            validate::string(value.as_str(), None, Some(32), path, out);
        }
        path.pop();
        path.push_key("customData");
        if let Some(value) = &self.custom_data {
            Validate::validate_at(value, path, out);
        }
        path.pop();
    }
}

