    /// Format as per RFC 3339: full-date  +
    ///
    /// Regex: (\[12\]\[0-9\]{3})-(0\[1-9\]\|1\[0-2\])-(0\[1-9\]\|\[12\]\[0-9\]\|3\[01\])
    #[serde(rename = "validFromDate")]
